func:
// Valida valores individuais; não impõe o mapa classe/destino/defeito.
// Horário ausente recebe o relógio do Node-RED; sincronize os nós do ensaio.
// Validar campos obrigatórios conforme levantamento:
// id_evento, horario, classe, destino, defeito

var id_evento = msg.payload.id_evento;
var classe    = msg.payload.classe;
var destino   = msg.payload.destino;
var defeito   = msg.payload.defeito;
var horario   = msg.payload.horario;

// Verificar campos obrigatórios
if (!id_evento || !classe || !destino || defeito === undefined) {
    node.error("Evento inválido: faltam campos obrigatórios", msg);
    return null;
}

// Verificar valores válidos
var classes_validas = ["QUADRADO", "TRIÂNGULO", "QUADRADO_COM_X"];
var destinos_validos = ["A", "B", "C"];

if (classes_validas.indexOf(classe) === -1) {
    node.error("Classe desconhecida: " + classe, msg);
    return null;
}

if (destinos_validos.indexOf(destino) === -1) {
    node.error("Destino desconhecido: " + destino, msg);
    return null;
}

if (typeof defeito !== 'boolean') {
    node.error("Campo defeito deve ser booleano", msg);
    return null;
}

msg.payload = {
    id_evento: id_evento,
    horario: horario || new Date().toISOString(),
    classe: classe,
    destino: destino,
    defeito: defeito,
    tempo_processamento_ms: msg.payload.tempo_processamento_ms ?? null,
    qualidade_segmentacao: msg.payload.qualidade_segmentacao ?? null,
    versao_calibracao: msg.payload.versao_calibracao ?? null
};

return msg;

// Cache volátil: reiniciar o Node-RED perde os IDs.
// O ID entra antes do HTTP; uma falha de escrita pode bloquear a retentativa.
// Evita reprocessamento de IDs conhecidos
// Armazena os últimos N IDs em memória

var id_evento = msg.payload.id_evento;
var ids_conhecidos = flow.get('ids_conhecidos') || [];

if (ids_conhecidos.indexOf(id_evento) !== -1) {
    node.warn("Evento duplicado ignorado: " + id_evento);
    return null;
}

// Adicionar ao histórico (manter últimos 100)
ids_conhecidos.push(id_evento);
if (ids_conhecidos.length > 100) {
    ids_conhecidos = ids_conhecidos.slice(-100);
}
flow.set('ids_conhecidos', ids_conhecidos);

return msg;

// Converte o evento para line protocol, com timestamp em milissegundos.
// IDs são campos, não tags: eventos no mesmo timestamp podem colidir.
var evento = msg.payload;
var token = env.get('INFLUXDB_TOKEN');

if (!token) {
    node.error('INFLUXDB_TOKEN não configurado', msg);
    return null;
}

function texto(valor) {
    return '"' + String(valor).replace(/\\/g, '\\\\').replace(/"/g, '\"') + '"';
}

var campos = [
    'id_evento=' + texto(evento.id_evento),
    'classe=' + texto(evento.classe),
    'destino=' + texto(evento.destino),
    'defeito=' + (evento.defeito ? 'true' : 'false')
];

if (evento.tempo_processamento_ms !== null && Number.isFinite(Number(evento.tempo_processamento_ms))) {
    campos.push('tempo_processamento_ms=' + Number(evento.tempo_processamento_ms));
}
if (evento.qualidade_segmentacao !== null && Number.isFinite(Number(evento.qualidade_segmentacao))) {
    campos.push('qualidade_segmentacao=' + Number(evento.qualidade_segmentacao));
}
if (evento.versao_calibracao !== null) {
    campos.push('versao_calibracao=' + texto(evento.versao_calibracao));
}

var timestamp = Date.parse(evento.horario);
if (!Number.isFinite(timestamp)) {
    node.error('Horário inválido: ' + evento.horario, msg);
    return null;
}

msg.method = 'POST';
msg.url = 'http://influxdb:8086/api/v2/write?org=tria&bucket=tria_events&precision=ms';
msg.headers = {
    'Authorization': 'Token ' + token,
    'Content-Type': 'text/plain; charset=utf-8'
};
msg.payload = 'triagem ' + campos.join(',') + ' ' + timestamp;
return msg;

// HTTP 204 confirma persistência; Debug anterior à escrita não confirma.
// Este fluxo registra erros, mas não possui fila persistente/retentativa.
if (msg.statusCode !== 204) {
    node.error('Falha ao gravar no InfluxDB. HTTP ' + msg.statusCode + ': ' + msg.payload, msg);
}
return null;
